import type {BankQuestion,BankQuiz} from './quizBank';
import type {BankSpot} from './quizPitch';
/**
 * More quizzes (Nov 23 2026; owner: "build more interactive quizzes for the quiz page" and "add more to history, terms and tactics,
 * and positions quizzes too"). MORE_QUESTIONS grows four quizzes of lib/site/quizBank.ts to twenty questions; NEW_QUIZZES are
 * twelve new ones, in the hub's topic order (rules, tactics, terms, history). Same rules as the first ten: every answer comes from a
 * page the site already checked (rules.ts and IFAB, sizes.ts and U.S. Soccer / US Youth Soccer, terms.ts, positionNumbers.ts,
 * formations.ts, the History Museum exhibits, the pop-up books), and each question links to that page. No question repeats one
 * in another quiz. New kinds: 'spot' (tap the place on the pitch, lib/site/quizPitch.ts) and 'order' (steps written in order).
 * The Spanish twin is lib/i18n/es/quizBank2.ts (same order, same answers, the same SPOTS).
 */
const R=(s:string)=>`/learn/soccer-rules/${s}`,T=(s:string)=>`/learn/soccer-terms/${s}`,P=(s:string)=>`/learn/soccer-positions/${s}`,X=(s:string)=>`/exhibits/${s}`;
const F=(s:string)=>`/learn/soccer-formations/${s}`,B=(s:string)=>`/books/${s}`;
const NUM='/learn/soccer-positions/numbers',BALL='/learn/soccer-ball-size-by-age',FIELD='/learn/soccer-field-size-by-age',AGES='/learn/soccer-age-groups',FMT='/learn/7v7-9v9-11v11';
const IFAB='https://www.theifab.com/laws/latest/';
const law=(n:string,page:string)=>({name:`IFAB Laws of the Game: ${n}`,url:IFAB+page});
const USS={name:'U.S. Soccer small-sided standards',url:'https://www.ussoccer.com/stories/2017/08/five-things-to-know-how-smallsided-standards-will-change-youth-soccer'};
const USYS={name:'US Youth Soccer: policy on players and playing rules (2025)',url:'https://www.usyouthsoccer.org/wp-content/uploads/sites/160/2025/12/Policy-on-Players-and-Playing-Rules-_APP-12.05.2025.pdf'};
const USSH={name:'U.S. Soccer: Recognize to Recover player safety program (heading)',url:'https://www.ussoccer.com/stories/2015/12/us-soccer-announces-recognize-to-recover-player-health-and-safety-program'};
const W=(t:string,page:string)=>({name:`Wikipedia: ${t}`,url:`https://en.wikipedia.org/wiki/${page}`});
const SITE=(t:string,path:string)=>({name:`Futbol Island: ${t}`,url:`https://futbolisland.app${path}`});
const c=(q:string,options:string[],correct:number,explain:string,more:string,fact?:string):BankQuestion=>({kind:'choice',q,options,correct,explain,more,...(fact?{fact}:{})});
const tf=(q:string,yes:boolean,explain:string,more:string):BankQuestion=>({kind:'truefalse',q,options:['True','False'],correct:yes?0:1,explain,more});
const sp=(q:string,options:string[],correct:number,explain:string,more:string,spot:BankSpot):BankQuestion=>({kind:'spot',q,options,correct,explain,more,spot});
const od=(q:string,steps:string[],explain:string,more:string):BankQuestion=>({kind:'order',q,options:steps,correct:0,explain,more});

